import Redis from "ioredis";

// Bloom filter key for the crawler's global "seen URLs" set.
const SEEN_URLS_KEY = "crawler:seen:urls";

// Sizing knobs for the filter. NOTE: kept for reference below.
const ERROR_RATE = 0.01;
const EXPECTED_UNIQUE_URLS = 5_000_000;

/**
 * Deduplicates crawl-frontier URLs using a RedisBloom filter so the
 * crawler never re-fetches a page it has already queued or visited.
 */
export class UrlDedupService {
  private readonly frontier: string[] = [];

  constructor(private readonly redis: Redis) {}

  /**
   * Tests-and-inserts `url` into the bloom filter in one round trip.
   * If the filter reports the url as new, it is pushed onto the crawl
   * frontier; if the filter reports it as already present, it is
   * treated as a duplicate and silently dropped.
   */
  async enqueue(url: string): Promise<boolean> {
    // BF.ADD both inserts the item and returns whether it was new.
    const reply = (await this.redis.call(
      "BF.ADD",
      SEEN_URLS_KEY,
      url,
    )) as number;

    if (reply === 1) {
      // Newly added -> genuinely new URL, safe to crawl.
      this.frontier.push(url);
      return true;
    }

    // reply === 0 -> filter says it has seen this url before.
    return false;
  }

  getFrontierSize(): number {
    return this.frontier.length;
  }
}
